    const {client, frames} = await connect(`${base}?sessionId=c-new`);

    const answer = await ask(client, frames, {type: 'list_conversations', userId: 'u2'});
    const cursor = {updatedAt: '2026-11-03T08:00:00.000Z', sessionId: 'c-new'};
    await ask(client, frames, {type: 'list_conversations', limit: 2, before: cursor});

    const list = answer.find(frame => frame.type === 'conversation_list');
    expect({
      types: answer.map(frame => frame.type),
      ids: list?.conversations?.map(row => row.sessionId),
      iso: list?.conversations?.every(row => ISO.test(String(row.createdAt)) && ISO.test(String(row.updatedAt))),
      head: list?.conversations?.[0],
      asked: store.asked,
    }).toEqual({
      types: ['conversation_list'],
      ids: ['c-new', 'c-mid', 'c-old'],
      iso: true,
      head: {sessionId: 'c-new', createdAt: expect.any(String), updatedAt: '2026-11-03T08:00:00.000Z', entryCount: 1},
      asked: [
        ['u1', {limit: undefined, before: undefined}],
        ['u1', {limit: 2, before: cursor}],
      ],
    });
  });

  it('refuses with one UNSUPPORTED error and no list when history is off or the store cannot list, and SERVER_ERROR when listing fails', async () => {
    const offBase = await startEngine(seed(new InMemorySessionStore(), THREE_FOR_U1));
    const off = await connect(`${offBase}?sessionId=c-new`);
    const historyOff = await ask(off.client, off.frames, {type: 'list_conversations'});

    const unlistableBase = await startEngine(withoutListFor(seed(new InMemorySessionStore(), THREE_FOR_U1)), HISTORY_ON);
    const unlistable = await connect(`${unlistableBase}?sessionId=c-new`);
    const noListFor = await ask(unlistable.client, unlistable.frames, {type: 'list_conversations'});

    const failing: SessionStore = {
      ...withoutListFor(seed(new InMemorySessionStore(), THREE_FOR_U1)),
      listFor: async () => {
        throw new Error('mongo: connection to db-7.internal refused for u1');
      },
    };
    const failingBase = await startEngine(failing, HISTORY_ON);
    const failed = await connect(`${failingBase}?sessionId=c-new`);
    const storeFailed = await ask(failed.client, failed.frames, {type: 'list_conversations'});

    const codes = (frames: Frame[]) => frames.map(frame => `${frame.type}:${frame.code ?? ''}`);
    expect({
      historyOff: codes(historyOff),
      noListFor: codes(noListFor),
      storeFailed: codes(storeFailed),
      leaksStoreDetail: /mongo|db-7|refused/.test(storeFailed[0]?.message ?? ''),
      stillOpen: failed.client.readyState === WebSocket.OPEN,
      loggedWithSession: errorsLogged.some(entry => JSON.stringify(entry).includes('c-new')),
    }).toEqual({
      historyOff: ['error:UNSUPPORTED'],
      noListFor: ['error:UNSUPPORTED'],
      storeFailed: ['error:SERVER_ERROR'],
      leaksStoreDetail: false,
      stillOpen: true,
      loggedWithSession: true,
    });
  });

  it("answers a list sent mid-stream before that turn's stream_end, off the session lock", async () => {
    const held = deferred();
    const holding: ChatOrchestrator = {
      processMessage: async () => 'hi',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'hi'};
        await held.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };
    const base = await startEngine(seed(new InMemorySessionStore(), THREE_FOR_U1), HISTORY_ON, holding);
    const {client, frames} = await connect(`${base}?sessionId=c-new`);

    client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
    await waitFor(() => frames.some(frame => frame.type === 'entry_delta'));
    client.send(JSON.stringify({type: 'list_conversations'}));
    await waitFor(() => frames.some(frame => frame.type === 'conversation_list' || frame.type === 'error'));
    held.release();
    await waitFor(() => frames.some(frame => frame.type === 'stream_end'));

    const order = frames.map(frame => frame.type).filter(type => ['conversation_list', 'stream_end'].includes(type));
    expect(order).toEqual(['conversation_list', 'stream_end']);
  });

  it('rejoins a conversation picked from the list through the existing ?sessionId= resume, replay included', async () => {
    const base = await startEngine(seed(new InMemorySessionStore(), THREE_FOR_U1), HISTORY_ON);
    const {client, frames} = await connect(base);
    const answer = await ask(client, frames, {type: 'list_conversations'});
    const picked = String(answer.find(frame => frame.type === 'conversation_list')?.conversations?.[2]?.sessionId);

    const rejoined = await connect(`${base}?sessionId=${picked}`);
    await ask(rejoined.client, rejoined.frames, {type: 'ping', timestamp: 1});

    expect({
      picked,
      connected: {sessionId: rejoined.connected.sessionId, resumed: rejoined.connected.resumed},
      replayed: rejoined.frames.filter(frame => frame.type === 'entry_upsert').length,
    }).toEqual({picked: 'c-mid', connected: {sessionId: 'c-mid', resumed: true}, replayed: 1});
  });
});

